"""Migration of legacy/opportunity_rules.vrl validation behavior."""

from decimal import Decimal


def _value(row: dict | None, field: str) -> object:
    if row is None:
        return ""
    value = row.get(field, "")
    return "" if value is None else value


def _numeric(value: object) -> Decimal:
    """Legacy numeric-context coercion: empty/missing values are zero."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _text(value: object) -> str:
    return "" if value is None else str(value)


def _date_equals_sentinel(value: object) -> bool:
    return _text(value) == "00000000"


def _date_greater_or_equal(left: object, right: object) -> bool:
    """Legacy date ordering, including the 00000000 no-value sentinel."""
    left_text = _text(left)
    right_text = _text(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Return all applicable legacy validation failures in rule-file order."""
    errors: list[dict] = []

    amt = _value(record, "AMT")
    stat_cd = _text(_value(record, "STAT_CD"))
    lost_rsn = _text(_value(record, "LOST_RSN"))
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    if event in ("INSERT", "UPDATE"):
        # OPP-001
        if _numeric(amt) < Decimal("0"):
            errors.append(
                {
                    "code": "E3001",
                    "message": "Amount negative",
                    "severity": "BLOCK",
                }
            )

        # OPP-002
        if stat_cd == "W" and _numeric(amt) == Decimal("0"):
            errors.append(
                {
                    "code": "E3002",
                    "message": "Won opportunity requires amount",
                    "severity": "BLOCK",
                }
            )

        # OPP-003
        if stat_cd == "L" and lost_rsn == "":
            errors.append(
                {
                    "code": "E3003",
                    "message": "Lost reason required",
                    "severity": "BLOCK",
                }
            )

        # OPP-004
        if stat_cd == "W" and _date_equals_sentinel(close_dt):
            errors.append(
                {
                    "code": "E3004",
                    "message": "Won opportunity requires close date",
                    "severity": "BLOCK",
                }
            )

    if event == "UPDATE":
        # OPP-005
        old_stat_cd = _text(_value(old, "STAT_CD"))
        if old_stat_cd == "W" and stat_cd != "W":
            errors.append(
                {
                    "code": "E3005",
                    "message": "Cannot reopen a won opportunity",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        # OPP-006
        stage_matches_status = (
            (stat_cd == "P" and _numeric(stage_pct) == Decimal("10"))
            or (stat_cd == "Q" and _numeric(stage_pct) == Decimal("25"))
            or (stat_cd == "N" and _numeric(stage_pct) == Decimal("60"))
            or (stat_cd == "W" and _numeric(stage_pct) == Decimal("100"))
            or (stat_cd == "L" and _numeric(stage_pct) == Decimal("0"))
        )
        if not stage_matches_status:
            errors.append(
                {
                    "code": "E3006",
                    "message": "Stage percent inconsistent with status",
                    "severity": "BLOCK",
                }
            )

    if event == "INSERT":
        # OPP-007
        if not (
            _date_equals_sentinel(close_dt)
            or _date_greater_or_equal(close_dt, today)
        ):
            errors.append(
                {
                    "code": "E3007",
                    "message": "Close date in past",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected legacy validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
